insert into public.owners (slug, name, city, country, country_code, since, wallet, verified, response_time, bio) values ('ramon-guaymas', 'Ramón Guaymás', 'Cafayate', 'Argentina', 'AR', 2024, '0x3a5c7e9b1d2f4a6c8e0b2d4f6a8c0e2b4d6f8a1c', true, '~30 min', 'Casa de adobe heredada de mi abuelo, con parral y patio. Recibo viajeros hace 9 años; te dejo una botella de torrontés de las bodegas de acá.') on conflict (slug) do nothing;
